def drop_point_routes(grid):
    rows, cols = len(grid), len(grid[0])
    every = [0] * cols   # routes into each cell of the current row
    clear = [0] * cols   # the routes among them that have met no drop point
    for i in range(rows):
        for j in range(cols):
            ch = grid[i][j]
            if ch == '#':
                every[j] = clear[j] = 0
                continue
            if i == 0 and j == 0:
                a = c = 1
            else:
                a = every[j] + (every[j - 1] if j else 0)
                c = clear[j] + (clear[j - 1] if j else 0)
            every[j] = a % MOD
            clear[j] = 0 if ch == 'P' else c % MOD
    return (every[-1] - clear[-1]) % MOD

