def drop_point_routes(grid):
    rows, cols = len(grid), len(grid[0])

    def count(si, sj, ei, ej):
        ways = [[0] * cols for _ in range(rows)]
        for i in range(si, ei + 1):
            for j in range(sj, ej + 1):
                if grid[i][j] == '#':
                    continue
                if (i, j) == (si, sj):
                    ways[i][j] = 1
                else:
                    ways[i][j] = ((ways[i - 1][j] if i > si else 0) + (ways[i][j - 1] if j > sj else 0)) % MOD
        return ways[ei][ej]

    total = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'P':
                total += count(0, 0, i, j) * count(i, j, rows - 1, cols - 1)
    return total % MOD

